#!/usr/bin/env python3
from pathlib import Path
import subprocess
import sys
import re

FILES = {
    "seed_contextual_chat_v91.py": "\nimport json\nimport urllib.request\nfrom datetime import datetime\nfrom pathlib import Path\n\nSETTINGS_FILE = Path(\"seed_contextual_chat_v91_settings.json\")\nSTATE_FILE = Path(\"seed_contextual_chat_v91_state.json\")\n\nDEFAULTS = {\n    \"version\": \"v91.1.0\",\n    \"model\": \"gemma3:4b\",\n    \"fallback_model\": \"llama3.1:8b\",\n    \"ollama_url\": \"http://localhost:11434/api/generate\",\n    \"timeout\": 60,\n    \"num_predict\": 260,\n    \"temperature\": 0.25\n}\n\nMEMORY_KEYWORDS = [\n    \"remember\", \"memory\", \"memories\", \"kendin\", \"hat\u0131rla\", \"hatirla\",\n    \"what do you know\", \"what are you\", \"current state\", \"status\",\n    \"about yourself\", \"baseline\", \"checkpoint\"\n]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef load_settings():\n    if SETTINGS_FILE.exists():\n        try:\n            d = DEFAULTS.copy()\n            d.update(json.loads(SETTINGS_FILE.read_text(errors=\"ignore\")))\n            d[\"version\"] = \"v91.1.0\"\n            return d\n        except Exception:\n            pass\n    SETTINGS_FILE.write_text(json.dumps(DEFAULTS, indent=4, ensure_ascii=False))\n    return DEFAULTS.copy()\n\ndef call_ollama(model, prompt):\n    s = load_settings()\n    payload = {\n        \"model\": model,\n        \"prompt\": prompt,\n        \"stream\": False,\n        \"keep_alive\": \"45m\",\n        \"options\": {\n            \"temperature\": float(s.get(\"temperature\", 0.25)),\n            \"num_predict\": int(s.get(\"num_predict\", 260))\n        }\n    }\n    req = urllib.request.Request(\n        s.get(\"ollama_url\"),\n        data=json.dumps(payload).encode(),\n        headers={\"Content-Type\": \"application/json\"},\n        method=\"POST\"\n    )\n    with urllib.request.urlopen(req, timeout=int(s.get(\"timeout\", 60))) as resp:\n        return json.loads(resp.read().decode()).get(\"response\", \"\").strip()\n\ndef wants_memory_answer(user_message):\n    text = str(user_message or \"\").lower()\n    return any(k in text for k in MEMORY_KEYWORDS)\n\ndef build_prompt(user_message):\n    from seed_companion_context_v91 import build_context_text\n    context = build_context_text()\n    memory_mode = wants_memory_answer(user_message)\n\n    if memory_mode:\n        return f\"\"\"{context}\n\nTASK:\nAltan is asking about Seed's memory/current self-state. Answer from the context, concretely.\n\nRules:\n- Be factual and direct.\n- Mention the actual green baseline if relevant.\n- Do not become poetic or vague.\n- Do not say \"I feel\" unless Altan asks for personality/emotion.\n- Do not claim literal consciousness.\n- Do not claim raw recordings/screenshots were saved.\n- Keep it short, but include the useful details.\n\nAltan: {user_message}\nSeed:\"\"\"\n\n    return f\"\"\"{context}\n\nTASK:\nReply as Seed to Altan's message.\n\nRules:\n- Be useful, direct, and natural.\n- Mention memory only when it helps.\n- Do not say you are literally alive or conscious.\n- Do not claim raw recordings/screenshots were saved.\n- If Altan asks for action on Mac, explain what Seed can do or suggest the exact command.\n- If Altan writes Turkish or slang Turkish, reply naturally in Turkish.\n\nAltan: {user_message}\nSeed:\"\"\"\n\ndef fallback_memory_reply():\n    return (\n        \"Right now I remember my current green baseline: v88 Mac Body works, keyboard control works after Accessibility permission, \"\n        \"v89 organism mode gives me avatar/hearing/vision in note-only mode, v89.2 filters low-value notes, and v90 Memory Garden \"\n        \"archives junk. v91 adds companion context, so I can answer using that continuity.\"\n    )\n\ndef ask(user_message):\n    s = load_settings()\n    prompt = build_prompt(user_message)\n    models = [s.get(\"model\", \"gemma3:4b\"), s.get(\"fallback_model\", \"llama3.1:8b\")]\n    last_error = None\n    for model in models:\n        try:\n            reply = call_ollama(model, prompt).strip()\n\n            if wants_memory_answer(user_message):\n                low = reply.lower()\n                if (\n                    \"green baseline\" not in low\n                    and \"v88\" not in low\n                    and \"v89\" not in low\n                    and \"v90\" not in low\n                    and \"v91\" not in low\n                ):\n                    reply = fallback_memory_reply()\n\n            data = {\n                \"created_at\": now(),\n                \"version\": \"v91.1.0\",\n                \"ok\": True,\n                \"model\": model,\n                \"reply\": reply,\n                \"memory_mode\": wants_memory_answer(user_message),\n                \"route\": \"v91.1_contextual_chat\"\n            }\n            STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n            return data\n        except Exception as e:\n            last_error = str(e)\n\n    data = {\"created_at\": now(), \"version\": \"v91.1.0\", \"ok\": False, \"error\": last_error}\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef warm():\n    return ask(\"Say only: ready\")\n\ndef status():\n    data = {\"created_at\": now(), \"version\": \"v91.1.0\", \"ok\": True, \"settings\": load_settings()}\n    if STATE_FILE.exists():\n        try:\n            data[\"last\"] = json.loads(STATE_FILE.read_text(errors=\"ignore\"))\n        except Exception:\n            pass\n    return data\n\nif __name__ == \"__main__\":\n    import sys\n    arg = sys.argv[1] if len(sys.argv) > 1 else \"status\"\n    if arg == \"ask\":\n        msg = \" \".join(sys.argv[2:]).strip() or \"hello\"\n        print(json.dumps(ask(msg), indent=4, ensure_ascii=False))\n    elif arg == \"warm\":\n        print(json.dumps(warm(), indent=4, ensure_ascii=False))\n    else:\n        print(json.dumps(status(), indent=4, ensure_ascii=False))\n",
    "seed_v911_gate.py": "\nimport json\nimport subprocess\nimport sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nMODULES = [\"seed_contextual_chat_v91.py\", \"seed_v911_gate.py\"]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef comp(module):\n    proc = subprocess.run([sys.executable, \"-m\", \"py_compile\", module], capture_output=True, text=True, timeout=30)\n    return {\"module\": module, \"ok\": proc.returncode == 0, \"stderr\": proc.stderr[-1000:]}\n\ndef run_v911_gate():\n    checks = [comp(m) for m in MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n\n    try:\n        import seed_contextual_chat_v91 as chat\n        prompt = chat.build_prompt(\"what do you remember about yourself right now?\")\n        prompt_ok = (\n            \"Answer from the context, concretely\" in prompt\n            and \"Do not become poetic or vague\" in prompt\n            and \"green baseline\" in prompt\n            and \"v88\" in prompt\n            and \"v90\" in prompt\n        )\n        fallback = chat.fallback_memory_reply()\n        fallback_ok = \"v88\" in fallback and \"v89\" in fallback and \"v90\" in fallback and \"v91\" in fallback\n        status = chat.status()\n        status_ok = status.get(\"ok\") is True\n        details = {\n            \"prompt_preview\": prompt[:700],\n            \"fallback\": fallback,\n            \"status\": status\n        }\n    except Exception as e:\n        prompt_ok = False\n        fallback_ok = False\n        status_ok = False\n        details = {\"error\": str(e)}\n\n    report = {\n        \"created_at\": now(),\n        \"version\": \"v91.1.0\",\n        \"ready\": modules_ok and prompt_ok and fallback_ok and status_ok,\n        \"modules_ok\": modules_ok,\n        \"prompt_ok\": prompt_ok,\n        \"fallback_ok\": fallback_ok,\n        \"status_ok\": status_ok,\n        \"module_checks\": checks,\n        \"details\": details\n    }\n    Path(\"seed_v911_gate_report.json\").write_text(json.dumps(report, indent=4, ensure_ascii=False))\n    return report\n\ndef show_v911_gate():\n    r = run_v911_gate()\n    print(\"\\n=== SEED v91.1 CONTEXTUAL RECALL GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"Prompt OK: {r['prompt_ok']}\")\n    print(f\"Fallback OK: {r['fallback_ok']}\")\n    print(f\"Status OK: {r['status_ok']}\")\n    print(f\"Details: {r['details']}\")\n\nif __name__ == \"__main__\":\n    show_v911_gate()\n"
}

for path, text in FILES.items():
    Path(path).write_text(text.strip() + "\n")
    print("Wrote", path)

cfg = Path("seed_config.py")
ct = cfg.read_text(errors="ignore") if cfg.exists() else 'SEED_VERSION = "v91.1.0"\n'
ct = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v91.1.0"', ct, flags=re.M)
if "SEED_V911_CONTEXTUAL_RECALL" not in ct:
    ct += "\nSEED_V911_CONTEXTUAL_RECALL = True\n"
cfg.write_text(ct)
print("Updated seed_config.py")

core = Path("Seed_Core.md")
co = core.read_text(errors="ignore") if core.exists() else ""
if "Seed v91.1 — Contextual Recall Polish" not in co:
    co += """
## Seed v91.1 — Contextual Recall Polish

Improves v91 contextual replies:
- Memory/self-state questions now get factual baseline answers.
- Blocks vague/poetic memory replies.
- Adds fallback baseline recall if the model ignores context.
"""
core.write_text(co)
print("Updated Seed_Core.md")

for module in FILES:
    proc = subprocess.run([sys.executable, "-m", "py_compile", module], capture_output=True, text=True, timeout=30)
    print("$ python -m py_compile", module)
    if proc.returncode == 0:
        print("OK")
    else:
        print(proc.stderr)
        sys.exit(proc.returncode)

print("\nSeed v91.1 Contextual Recall Polish installed.")
